from collections import deque

def build_adj_list(grid, color):
    rows = len(grid)
    cols = len(grid[0])
    adj = []
    for r in range(rows):
        row_adj = []
        for c in range(cols):
            if grid[r][c] == color:
                neighbors = []
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == color:
                        neighbors.append((nr, nc))
                row_adj.append(len(neighbors))  # degree
            else:
                row_adj.append(-1)
        adj.append(row_adj)
    return adj

