5 0 5 0 0 0 5 5 5 5 5 5 5 5 5 0 5 0"""

g = [[int(x) for x in row.split()] for row in current_grid_str.strip().split('\n')]

# Find 3x3 regions with a clear majority (>4 cells of one color)
majority_positions = {}
for r in range(15):
    for c in range(15):
        counts = {}
        for dr in range(3):
            for dc in range(3):
                val = g[r+dr][c+dc]
                counts[val] = counts.get(val, 0) + 1
        # Find majority
        if max(counts.values()) > 4:
            r_out, c_out = r//3, c//3
            maj_color = max(counts, key=lambda k: counts[k])
            majority_positions[(r_out, c_out)] = (maj_color, counts)

print("3x3 regions with majority (>4 of one color):")
for pos in sorted(majority_positions):
    color, counts = majority_positions[pos]
    print(f"  {pos}: majority {color}, counts {counts}")

# But 0 is background - maybe we only count 4 and 5?
print("\nSkipping 0, only counting 4 and 5:")
majority_positions_45 = {}
for r in range(15):
    for c in range(15):
        counts = {}
        for dr in range(3):
            for dc in range(3):
                val = g[r+dr][c+dc]
                if val in (4, 5):
                    counts[val] = counts.get(val, 0) + 1
        if counts and max(counts.values()) > 4:
            r_out, c_out = r//3, c//3
            maj_color = max(counts, key=lambda k: counts[k])
            majority_positions_45[(r_out, c_out)] = (maj_color, counts)

print("3x3 regions with majority (>4 of 4 or 5):")
for pos in sorted(majority_positions_45):
    color, counts = majority_positions_45[pos]
    print(f"  {pos}: majority {color}, counts {counts}")

# The MAJORITY rule might require all cells in 3x3 to be only 4 or 5 (no 0s)?
print("\n3x3 with majority among 4/5 and ONLY 4/5 (no 0):")
strict_positions = {}
for r in range(15):
    for c in range(15):
        counts = {}
        no_zero = True
        for dr in range(3):
            for dc in range(3):
                val = g[r+dr][c+dc]
                if val == 0:
                    no_zero = False
                elif val in (4, 5):
                    counts[val] = counts.get(val, 0) + 1
        if no_zero and counts and max(counts.values()) > 4:
            r_out, c_out = r//3, c//3
            maj_color = max(counts, key=lambda k: counts[k])
            strict_positions[(r_out, c_out)] = (maj_color, counts)

print("Strict 3x3 (no 0s, majority 4/5):")
for pos in sorted(strict_positions):
    color, counts = strict_positions[pos]
    print(f"  {pos}: majority {color}, counts {counts}")

